toolCalls.args:
{"command": "# Try llvm-addr2line which gives cleaner function name output
which llvm-addr2line 2>/dev/null && {
  DWARF=/tmp/libcoreclr.dSYM/Contents/Resources/DWARF/libcoreclr
  for offset in 0x3e1700 0x2615fc 0x16c31c 0x16c620 0x18b678 0x49cc; do
    echo -n "Offset $offset: "
    llvm-addr2line -f -e "$DWARF" "$offset" 2>&1
  done
} || echo "llvm-addr2line not found"", "description": "Symbolicate with addr2line"}
